changeSet.sql:
CREATE TEMPORARY TABLE variant_survivor AS SELECT l.group_id, (ARRAY_AGG(l.test_id ORDER BY (CASE WHEN t.is_active = 'Y' THEN 0 ELSE 1 END), l.test_id))[1] AS survivor_id FROM clinlims.test_variant_link l JOIN clinlims.test t ON t.id = l.test_id GROUP BY l.group_id;
INSERT INTO clinlims.sampletype_test (id, sample_type_id, test_id, is_panel) SELECT nextval('clinlims.sample_type_test_seq'), d.sample_type_id, d.survivor_id, 'false' FROM ( SELECT DISTINCT st.sample_type_id, s.survivor_id FROM clinlims.test_variant_link l JOIN variant_survivor s ON s.group_id = l.group_id JOIN clinlims.sampletype_test st ON st.test_id = l.test_id WHERE l.test_id <> s.survivor_id AND NOT EXISTS (SELECT 1 FROM clinlims.sampletype_test x WHERE x.test_id = s.survivor_id AND x.sample_type_id = st.sample_type_id) ) d;
UPDATE clinlims.test SET is_active = 'N', orderable = false, lastupdated = NOW() WHERE id IN ( SELECT l.test_id FROM clinlims.test_variant_link l JOIN variant_survivor s ON s.group_id = l.group_id WHERE l.test_id <> s.survivor_id );
DROP TABLE variant_survivor;
